compileResult.css:
@import "~/assets/styles/custom-media-query.css";

#pages-photo[data-v-b7bbb04b]{display: grid;
  row-gap: 1.5rem;}

  @media (--mobile) {#pages-photo[data-v-b7bbb04b]{row-gap: 1rem;}}

  #pages-photo h1[data-v-b7bbb04b]{font-family: "ClashDisplay-Semibold";
    font-size: 3rem;
    padding: 7.5rem 0;
    margin: 0;}

    @media (--mobile) {#pages-photo h1[data-v-b7bbb04b]{padding: 2.5rem 0.75rem;}}

.photo-description[data-v-b7bbb04b]{color: var(--color-text-default);
  font-size: 16px;
  line-height: 1.8;
  margin-bottom: 24px;}

  @media (--mobile) {.photo-description[data-v-b7bbb04b]{font-size: 14px;
    margin-bottom: 16px;}}

.cc0-link[data-v-b7bbb04b]{color: var(--color-primary-base);
  text-decoration: underline;
  transition: opacity 0.2s ease;}

  .cc0-link[data-v-b7bbb04b]:hover{opacity: 0.7;}

.photo-list[data-v-b7bbb04b]{list-style: disc;
  padding-left: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;}

  @media (--mobile) {.photo-list[data-v-b7bbb04b]{padding-left: 20px;
    gap: 8px;}}

.photo-list-item[data-v-b7bbb04b]{color: var(--color-text-default);}

.photo-link[data-v-b7bbb04b]{color: var(--color-primary-base);
  text-decoration: none;
  font-size: 16px;
  transition: opacity 0.2s ease;}

  .photo-link[data-v-b7bbb04b]:hover{opacity: 0.7;
    text-decoration: underline;}

  @media (--mobile) {.photo-link[data-v-b7bbb04b]{font-size: 14px;}}

